@Serializable sealed interface PhoneRoute {
    // 5 Fő Tab a BottomNavigationBar-ban
    @Serializable data object HomeTab : PhoneRoute          // Kezdőlap, Mai terv, Aktív edzés sáv, Óra & Egészség gyorstükör
    @Serializable data object TrainingTab : PhoneRoute      // Edzés: Aktív edzés, Programok, Naptár, Gyakorlat-katalógus (#107)
    @Serializable data object JournalTab : PhoneRoute       // Napló: Edzéselőzmények, #226/#234 PR chip, #193 GPS térkép
    @Serializable data object ProgressTab : PhoneRoute      // Fejlődés: #177 Izom-anatómia, 1RM/Volumen trendek, Testsúly & Fotók
    @Serializable data object HealthTab : PhoneRoute        // Egészség: #120/#168 Egészségnapló (26 metrika), #111 BLE Discovery

    // Másodlagos / Részletes Képernyők és Teljes Képernyős Nézetek
    @Serializable data class ActiveWorkoutScreenRoute(val workoutId: String) : PhoneRoute
    @Serializable data class ProgramEditorRoute(val programId: String? = null) : PhoneRoute
    @Serializable data class WorkoutRouteMapScreenRoute(val workoutId: String, val routeKey: String) : PhoneRoute
    @Serializable data object BleDiscoveryScreenRoute : PhoneRoute
    @Serializable data object SettingsAndBackupRoute : PhoneRoute
    @Serializable data object PrivacyPolicyRoute : PhoneRoute
}
